def calculate_walk_value(walk_set: str) -> int:
    MOD = 10**9 + 7

    # Precompute powers of 2 up to the length of the walk_set
    max_length = len(walk_set)
    powers_of_2 = [1] * (max_length + 1)
    for i in range(1, max_length + 1):
        powers_of_2[i] = (powers_of_2[i - 1] * 2) % MOD

    # Dynamic programming to calculate the value of the set of walks
    dp = [0] * (max_length + 1)
    dp[0] = 1  # Base case: one way to have an empty walk

    for i in range(1, max_length + 1):
        if walk_set[i - 1] == 'L':
            dp[i] = dp[i - 1]
        elif walk_set[i - 1] == 'R':
            dp[i] = dp[i - 1]
        elif walk_set[i - 1] == 'P':
            dp[i] = dp[i - 1]
        elif walk_set[i - 1] == '*':
            dp[i] = (dp[i - 1] * 3) % MOD

    # Calculate the total value of the set of walks
    total_value = 0
    current_position = 1  # Start at the root node with value 1

    for i in range(1, max_length + 1):
        if walk_set[i - 1] == 'L':
            current_position *= 2
        elif walk_set[i - 1] == 'R':
            current_position = current_position * 2 + 1
        elif walk_set[i - 1] == '*':
            total_value = (total_value + current_position * dp[i]) % MOD
        # For 'P', we do nothing as it stays at the same node

    return total_value

