    def calculate_value(walk: str) -> int:
        current_value = 1
        for move in walk:
            if move == 'L':
                current_value = 2 * current_value
            elif move == 'R':
                current_value = 2 * current_value + 1
            # 'P' means stay in the same node, so no change in current_value
        return current_value

    def generate_walks(walk_set: str) -> list:
        if not walk_set:
            return ['']
        if walk_set[0] == '*':
            rest_walks = generate_walks(walk_set[1:])
            return ['L' + walk for walk in rest_walks] + \
                   ['R' + walk for walk in rest_walks] + \
                   ['P' + walk for walk in rest_walks]
        else:
            rest_walks = generate_walks(walk_set[1:])
            return [walk_set[0] + walk for walk in rest_walks]

    walks = generate_walks(walk_set)
    total_value = sum(calculate_value(walk) for walk in walks)
    return total_value

